package com.aicharacter.v3;
public final class PlanDiagnostics{private PlanDiagnostics(){}public static String trace(WorldState s){PlanState p=s.planState;return "Plan ID: "+p.planId+"\nIntention: "+p.intentionId+"\nGoal: "+p.goal+"\nState: "+p.status+"\nStep: "+p.stepIndex+" / "+p.steps+"\nDestination: "+p.destination+"\nTravel: "+s.girlTravel.currentSegment()+" "+(int)(s.girlTravel.progress*100)+"%\nCommitment: "+String.format(java.util.Locale.US,"%.2f",p.commitment)+"\nLast decision: "+p.lastDecision+"\nReasons: "+p.lastReason+"\nLast arrival: "+p.lastArrival+"\nLast action: "+p.lastAction+"\nLast outcome: "+p.lastOutcome+"\nPause: "+p.pauseReason;}}
